// @FIGURE_CODE_BEGIN
(function(){
  var W = 600, H = 450;
  var draw = SVG().addTo(document.getElementById('container')).size('100%','100%');
  draw.viewbox(0,0,W,H);

  setPlotFrame({ xDomain: [-2, 4], yDomain: [-2, 2], margin: 45, draw: draw });

  // Physics
  var QP = {x:0, y:0};  // positive charge
  var QN = {x:2, y:0};  // negative charge

  function fieldAt(x, y) {
    var dx1 = x - QP.x, dy1 = y - QP.y;
    var r1 = Math.sqrt(dx1*dx1 + dy1*dy1);
    if (r1 < 0.05) r1 = 0.05;
    var r1_3 = r1*r1*r1;
    var ex1 = dx1/r1_3, ey1 = dy1/r1_3;

    var dx2 = x - QN.x, dy2 = y - QN.y;
    var r2 = Math.sqrt(dx2*dx2 + dy2*dy2);
    if (r2 < 0.05) r2 = 0.05;
    var r2_3 = r2*r2*r2;
    var ex2 = -dx2/r2_3, ey2 = -dy2/r2_3;

    return { ex: ex1+ex2, ey: ey1+ey2, ex1: ex1, ey1: ey1, ex2: ex2, ey2: ey2, mag: Math.sqrt((ex1+ex2)*(ex1+ex2)+(ey1+ey2)*(ey1+ey2)) };
  }

  // State
  var showFieldLines = false;
  var gridDensity = 16;
  var hoverActive = false;

  // Groups
  var gAxes = draw.group();
  var gArrows = draw.group();
  var gFieldLines = draw.group();
  var gHover = draw.group();
  var gLabels = draw.group();

  // Draw axes
  function drawAxes() {
    gAxes.clear();
    var x0 = plotX(-2), x1 = plotX(4), y0 = plotY(2), y1 = plotY(-2);
    // Frame
    gAxes.rect(x1-x0, y1-y0).move(x0, y0).fill('none').stroke({color:'#333', width:1.2});
    // X ticks
    for (var tx = -2; tx <= 4; tx++) {
      var sx = plotX(tx);
      gAxes.line(sx, y1, sx, y1+5).stroke({color:'#333', width:1});
      gAxes.text(String(tx)).font({size:11, family:'sans-serif'}).attr({x:sx, y:y1+8, 'text-anchor':'middle', fill:'#333'});
    }
    // Y ticks
    for (var ty = -2; ty <= 2; ty++) {
      var sy = plotY(ty);
      gAxes.line(x0-5, sy, x0, sy).stroke({color:'#333', width:1});
      gAxes.text(String(ty)).font({size:11, family:'sans-serif'}).attr({x:x0-8, y:sy+4, 'text-anchor':'end', fill:'#333'});
    }
    // Axis labels
    gAxes.text('x (m)').font({size:13, family:'sans-serif', weight:'bold'}).attr({x:(x0+x1)/2, y:y1+24, 'text-anchor':'middle', fill:'#333'});
    gAxes.text('y (m)').font({size:13, family:'sans-serif', weight:'bold'}).attr({x:x0-30, y:(y0+y1)/2, 'text-anchor':'middle', fill:'#333', transform:'rotate(-90,'+(x0-30)+','+((y0+y1)/2)+')'});
  }

  // Arrow drawing helper
  function drawArrow(group, cx, cy, dx, dy, len, color, headSize) {
    if (len < 1.5) {
      group.circle(2.5).center(cx, cy).fill(color).stroke('none');
      return;
    }
    var ux = dx/len, uy = dy/len;
    var tipX = cx + ux*len, tipY = cy + uy*len;
    var tailX = cx - ux*len, tailY = cy - uy*len;
    group.line(tailX, tailY, tipX, tipY).stroke({color:color, width:1.2, linecap:'round'});
    // Arrowhead
    var hs = Math.min(headSize || 4, len*0.4);
    var angle = Math.atan2(uy, ux);
    var a1 = angle + Math.PI*0.82, a2 = angle - Math.PI*0.82;
    group.line(tipX, tipY, tipX + hs*Math.cos(a1), tipY + hs*Math.sin(a1)).stroke({color:color, width:1.2, linecap:'round'});
    group.line(tipX, tipY, tipX + hs*Math.cos(a2), tipY + hs*Math.sin(a2)).stroke({color:color, width:1.2, linecap:'round'});
  }

  // Draw arrow grid
  function drawArrowGrid() {
    gArrows.clear();
    if (showFieldLines) return;
    var n = gridDensity;
    var xMin = -2, xMax = 4, yMin = -2, yMax = 2;
    var dx = (xMax - xMin) / (n - 1);
    var ny = Math.round((yMax - yMin) / dx) + 1;
    var dy = (yMax - yMin) / (ny - 1);
    var maxArrowPx = 14;
    var arrowColor = '#1e3a5f';

    for (var i = 0; i < n; i++) {
      for (var j = 0; j < ny; j++) {
        var wx = xMin + i * dx;
        var wy = yMin + j * dy;
        var f = fieldAt(wx, wy);
        var mag = f.mag;
        // Scale: use power law to compress dynamic range
        var scaledLen = maxArrowPx * Math.pow(mag / 2.0, 0.35);
        if (scaledLen > maxArrowPx) scaledLen = maxArrowPx;
        if (scaledLen < 0.5) scaledLen = 0.5;
        var px = plotX(wx), py = plotY(wy);
        var sdx = f.ex / mag * scaledLen;
        var sdy = -f.ey / mag * scaledLen; // flip y for screen
        drawArrow(gArrows, px, py, sdx, sdy, scaledLen, arrowColor, 3.5);
      }
    }
  }

  // Draw field lines using RK4
  function drawFieldLines() {
    gFieldLines.clear();
    if (!showFieldLines) return;
    var numLines = 14;
    var lineColor = '#1e3a5f';
    var stepSize = 0.015;
    var maxSteps = 2000;

    for (var k = 0; k < numLines; k++) {
      var angle = (2 * Math.PI * k) / numLines;
      var startX = QP.x + 0.12 * Math.cos(angle);
      var startY = QP.y + 0.12 * Math.sin(angle);
      var pts = [];
      var x = startX, y = startY;
      var terminated = false;

      for (var s = 0; s < maxSteps; s++) {
        pts.push([plotX(x), plotY(y)]);
        // RK4
        var f1 = fieldAt(x, y);
        var m1 = Math.sqrt(f1.ex*f1.ex + f1.ey*f1.ey);
        if (m1 < 1e-10) break;
        var k1x = f1.ex/m1, k1y = f1.ey/m1;

        var f2 = fieldAt(x + stepSize/2*k1x, y + stepSize/2*k1y);
        var m2 = Math.sqrt(f2.ex*f2.ex + f2.ey*f2.ey);
        if (m2 < 1e-10) break;
        var k2x = f2.ex/m2, k2y = f2.ey/m2;

        var f3 = fieldAt(x + stepSize/2*k2x, y + stepSize/2*k2y);
        var m3 = Math.sqrt(f3.ex*f3.ex + f3.ey*f3.ey);
        if (m3 < 1e-10) break;
        var k3x = f3.ex/m3, k3y = f3.ey/m3;

        var f4 = fieldAt(x + stepSize*k3x, y + stepSize*k3y);
        var m4 = Math.sqrt(f4.ex*f4.ex + f4.ey*f4.ey);
        if (m4 < 1e-10) break;
        var k4x = f4.ex/m4, k4y = f4.ey/m4;

        x += stepSize/6*(k1x + 2*k2x + 2*k3x + k4x);
        y += stepSize/6*(k1y + 2*k2y + 2*k3y + k4y);

        // Check termination
        var dNeg = Math.sqrt((x-QN.x)*(x-QN.x) + (y-QN.y)*(y-QN.y));
        if (dNeg < 0.1) { terminated = true; break; }
        if (x < -2.1 || x > 4.1 || y < -2.1 || y > 2.1) break;
      }

      if (pts.length > 3) {
        var ptsStr = pts.map(function(p){ return p[0]+','+p[1]; }).join(' ');
        gFieldLines.polyline(ptsStr).fill('none').stroke({color: lineColor, width: 1.3, linecap:'round', linejoin:'round'});
        // Arrowhead at midpoint
        var mid = Math.floor(pts.length * 0.5);
        if (mid > 0 && mid < pts.length - 1) {
          var mx = pts[mid][0], my = pts[mid][1];
          var nx = pts[mid+1][0] - pts[mid-1][0], ny2 = pts[mid+1][1] - pts[mid-1][1];
          var nl = Math.sqrt(nx*nx + ny2*ny2);
          if (nl > 0) {
            nx /= nl; ny2 /= nl;
            var hs = 5;
            var a1 = Math.atan2(ny2, nx) + Math.PI*0.82;
            var a2 = Math.atan2(ny2, nx) - Math.PI*0.82;
            gFieldLines.line(mx, my, mx+hs*Math.cos(a1), my+hs*Math.sin(a1)).stroke({color:lineColor, width:1.2});
            gFieldLines.line(mx, my, mx+hs*Math.cos(a2), my+hs*Math.sin(a2)).stroke({color:lineColor, width:1.2});
          }
        }
      }
    }
  }

  // Hover interaction
  var hoverRect = draw.rect(plotX(4)-plotX(-2), plotY(-2)-plotY(2)).move(plotX(-2), plotY(2)).fill('transparent').stroke('none');
  hoverRect.css('cursor','crosshair');

  hoverRect.on('mousemove', function(e) {
    var rect = draw.node.getBoundingClientRect();
    var vb = draw.viewbox();
