  }

  // Draw arrow grid
  function drawArrowGrid() {
    gArrows.clear();
    if (showFieldLines) return;
    var n = gridDensity;
    var xMin = -2, xMax = 4, yMin = -2, yMax = 2;
    var dx = (xMax - xMin) / (n - 1);
    var ny = Math.round((yMax - yMin) / dx) + 1;
    var dy = (yMax - yMin) / (ny - 1);
    var maxArrowPx = 14;
    var arrowColor = '#1e3a5f';

    for (var i = 0; i < n; i++) {
      for (var j = 0; j < ny; j++) {
        var wx = xMin + i * dx;
        var wy = yMin + j * dy;
        var f = fieldAt(wx, wy);
        var mag = f.mag;
        // Scale: use power law to compress dynamic range
        var scaledLen = maxArrowPx * Math.pow(mag / 2.0, 0.35);
        if (scaledLen > maxArrowPx) scaledLen = maxArrowPx;
        if (scaledLen < 0.5) scaledLen = 0.5;
        var px = plotX(wx), py = plotY(wy);
        var sdx = f.ex / mag * scaledLen;
        var sdy = -f.ey / mag * scaledLen; // flip y for screen
        drawArrow(gArrows, px, py, sdx, sdy, scaledLen, arrowColor, 3.5);
      }
    }
  }

  // Draw field lines using RK4
  function drawFieldLines() {
    gFieldLines.clear();
    if (!showFieldLines) return;
    var numLines = 14;
    var lineColor = '#1e3a5f';
    var stepSize = 0.015;
    var maxSteps = 2000;

    for (var k = 0; k < numLines; k++) {
      var angle = (2 * Math.PI * k) / numLines;
      var startX = QP.x + 0.12 * Math.cos(angle);
      var startY = QP.y + 0.12 * Math.sin(angle);
      var pts = [];
      var x = startX, y = startY;
      var terminated = false;

      for (var s = 0; s < maxSteps; s++) {
        pts.push([plotX(x), plotY(y)]);
        // RK4
        var f1 = fieldAt(x, y);
        var m1 = Math.sqrt(f1.ex*f1.ex + f1.ey*f1.ey);
        if (m1 < 1e-10) break;
        var k1x = f1.ex/m1, k1y = f1.ey/m1;

        var f2 = fieldAt(x + stepSize/2*k1x, y + stepSize/2*k1y);
        var m2 = Math.sqrt(f2.ex*f2.ex + f2.ey*f2.ey);
        if (m2 < 1e-10) break;
        var k2x = f2.ex/m2, k2y = f2.ey/m2;

        var f3 = fieldAt(x + stepSize/2*k2x, y + stepSize/2*k2y);
        var m3 = Math.sqrt(f3.ex*f3.ex + f3.ey*f3.ey);
        if (m3 < 1e-10) break;
        var k3x = f3.ex/m3, k3y = f3.ey/m3;

        var f4 = fieldAt(x + stepSize*k3x, y + stepSize*k3y);
        var m4 = Math.sqrt(f4.ex*f4.ex + f4.ey*f4.ey);
        if (m4 < 1e-10) break;
        var k4x = f4.ex/m4, k4y = f4.ey/m4;

        x += stepSize/6*(k1x + 2*k2x + 2*k3x + k4x);
        y += stepSize/6*(k1y + 2*k2y + 2*k3y + k4y);

        // Check termination
        var dNeg = Math.sqrt((x-QN.x)*(x-QN.x) + (y-QN.y)*(y-QN.y));
        if (dNeg < 0.1) { terminated = true; break; }
        if (x < -2.1 || x > 4.1 || y < -2.1 || y > 2.1) break;
      }

      if (pts.length > 3) {
        var ptsStr = pts.map(function(p){ return p[0]+','+p[1]; }).join(' ');
        gFieldLines.polyline(ptsStr).fill('none').stroke({color: lineColor, width: 1.3, linecap:'round', linejoin:'round'});
        // Arrowhead at midpoint
        var mid = Math.floor(pts.length * 0.5);
        if (mid > 0 && mid < pts.length - 1) {
          var mx = pts[mid][0], my = pts[mid][1];
          var nx = pts[mid+1][0] - pts[mid-1][0], ny2 = pts[mid+1][1] - pts[mid-1][1];
          var nl = Math.sqrt(nx*nx + ny2*ny2);
          if (nl > 0) {
            nx /= nl; ny2 /= nl;
            var hs = 5;
            var a1 = Math.atan2(ny2, nx) + Math.PI*0.82;
            var a2 = Math.atan2(ny2, nx) - Math.PI*0.82;
            gFieldLines.line(mx, my, mx+hs*Math.cos(a1), my+hs*Math.sin(a1)).stroke({color:lineColor, width:1.2});
            gFieldLines.line(mx, my, mx+hs*Math.cos(a2), my+hs*Math.sin(a2)).stroke({color:lineColor, width:1.2});
          }
        }
      }
    }
  }

  // Hover interaction
  var hoverRect = draw.rect(plotX(4)-plotX(-2), plotY(-2)-plotY(2)).move(plotX(-2), plotY(2)).fill('transparent').stroke('none');
  hoverRect.css('cursor','crosshair');

  hoverRect.on('mousemove', function(e) {
    var rect = draw.node.getBoundingClientRect();
    var vb = draw.viewbox();
    var sx = (e.clientX - rect.left) / rect.width * vb.width;
    var sy = (e.clientY - rect.top) / rect.height * vb.height;
    // Convert to world
    var f = _plotFrame;
    var wx = f.xDomain[0] + (sx - f.margin) / f.sx;
    var wy = f.yDomain[0] + (f.height - f.margin - sy) / f.sy;

    // Find nearest grid point
    var n = gridDensity;
    var xMin = -2, xMax = 4, yMin = -2, yMax = 2;
    var dx = (xMax - xMin) / (n - 1);
    var ny = Math.round((yMax - yMin) / dx) + 1;
    var dy = (yMax - yMin) / (ny - 1);
    var gi = Math.round((wx - xMin) / dx);
    var gj = Math.round((wy - yMin) / dy);
    gi = Math.max(0, Math.min(n-1, gi));
    gj = Math.max(0, Math.min(ny-1, gj));
    var gx = xMin + gi * dx;
    var gy = yMin + gj * dy;

    showHoverDecomposition(gx, gy, e);
  });

  hoverRect.on('mouseleave', function() {
    gHover.clear();
    hideTooltip();
  });

  function showHoverDecomposition(wx, wy, event) {
    gHover.clear();
    var f = fieldAt(wx, wy);
    var px = plotX(wx), py = plotY(wy);
    var scale = 30; // pixels per unit field for hover arrows

    // Contribution from + charge (orange)
    var e1mag = Math.sqrt(f.ex1*f.ex1 + f.ey1*f.ey1);
    var e1len = Math.min(scale * Math.pow(e1mag, 0.5), 60);
    var e1dx = f.ex1/e1mag * e1len;
    var e1dy = -f.ey1/e1mag * e1len;

    // Contribution from - charge (green)
    var e2mag = Math.sqrt(f.ex2*f.ex2 + f.ey2*f.ey2);
    var e2len = Math.min(scale * Math.pow(e2mag, 0.5), 60);
    var e2dx = f.ex2/e2mag * e2len;
    var e2dy = -f.ey2/e2mag * e2len;

    // Resultant
    var emag = f.mag;
    var elen = Math.min(scale * Math.pow(emag, 0.5), 70);
    var edx = f.ex/emag * elen;
    var edy = -f.ey/emag * elen;

    // Draw tip-to-tail: orange from point, green from tip of orange
    // Orange arrow (from + charge contribution)
    drawArrow(gHover, px, py, e1dx, e1dy, e1len, '#e67e22', 5);
    // Green arrow (from - charge contribution), starting at tip of orange
    drawArrow(gHover, px+e1dx, py+e1dy, e2dx, e2dy, e2len, '#27ae60', 5);
    // Resultant (blue, thicker)
    gHover.line(px, py, px+edx, py+edy).stroke({color:'#1a5276', width:2.5, linecap:'round'});
    var ra = Math.atan2(edy, edx);
    var rhs = 7;
    gHover.line(px+edx, py+edy, px+edx+rhs*Math.cos(ra+Math.PI*0.82), py+edy+rhs*Math.sin(ra+Math.PI*0.82)).stroke({color:'#1a5276', width:2.5, linecap:'round'});
    gHover.line(px+edx, py+edy, px+edx+rhs*Math.cos(ra-Math.PI*0.82), py+edy+rhs*Math.sin(ra-Math.PI*0.82)).stroke({color:'#1a5276', width:2.5, linecap:'round'});

    // Dot at grid point
    gHover.circle(5).center(px, py).fill('#c0392b').stroke({color:'#fff', width:1});

    // Label
    var magStr = emag.toFixed(2);
    gHover.text('|E| = ' + magStr).font({size:11, family:'sans-serif', weight:'bold'}).attr({x:px+10, y:py-12, fill:'#1a5276', 'paint-order':'stroke', stroke:'#fff', 'stroke-width':3, 'stroke-linejoin':'round'});

    showTooltip('Field at (' + wx.toFixed(1) + ', ' + wy.toFixed(1) + ')\nOrange: from + charge\nGreen: from − charge\nBlue: resultant (sum)', event);
  }

  // Render all
  function render() {
    drawAxes();
    drawArrowGrid();
    drawFieldLines();
  }

  render();

  // Controls
  window.toggle_viewToggle = function(on) {
    showFieldLines = on;
    render();
  };

  window.update_gridDensity = function(v) {
    gridDensity = v;
    render();
  };

  // Demo steps
  var steps = [
    { title: 'Read the arrow grid', narration: 'The dark-blue arrows sample the dipole field on a regular grid: they point radially outward around (0,0) and radially inward around (2,0), fading to dots far from both centers.', state: { viewToggle: false, gridDensity: 16 } },
    { title: 'Decompose one arrow', narration: 'Hover any grid point: the arrow enlarges with a magnitude readout, and two colored contribution arrows (outward from the + charge, inward toward the − charge) add tip-to-tail to reproduce it — the local field is a superposition.', state: { viewToggle: false, gridDensity: 16 } },
    { title: 'Vary the sampling', narration: 'Drag the density slider: the grid becomes sparser or denser, yet the outward/inward dipole pattern is unchanged — confirming the clutter comes from the representation, not the physics.', state: { viewToggle: false, gridDensity: 8 } },
    { title: 'Switch to field lines', narration: 'Toggle to field lines: the hundreds of arrows are replaced by smooth continuous curves flowing from the + charge to the − charge, encoding the same directions with much less visual noise.', state: { viewToggle: true, gridDensity: 16 } }
  ];
  var currentStep = 0;

  function applyStep(idx) {
    currentStep = idx;
    var s = steps[idx];
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepLabel').textContent = (idx+1) + '/' + steps.length;
    // Apply state
    document.getElementById('viewToggleInput').checked = s.state.viewToggle;
    showFieldLines = s.state.viewToggle;
    document.getElementById('gridDensityInput').value = s.state.gridDensity;
    document.getElementById('gridDensityVal').value = s.state.gridDensity;
    gridDensity = s.state.gridDensity;
    render();
  }

  window.prevStep = function() { if (currentStep > 0) applyStep(currentStep - 1); };
  window.nextStep = function() { if (currentStep < steps.length - 1) applyStep(currentStep + 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The electric field of a dipole is the vector sum of two point-charge fields, and an arrow grid versus continuous field lines are two representations of that same field — the visual clutter belongs to the representation, not to the physics.
KEY INSIGHT (what students should walk away understanding): An arrow grid and a set of field lines are two drawings of the same dipole field, and every arrow is just the vector sum of the two point-charge contributions — so the apparent complexity is in the picture, not in the field.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
